export function saarAccountDate(read:SaarReadResult){const value=read.disabledBySigned&&read.disabledDate?read.disabledDate:read.createdBySigned&&read.createdDate?read.createdDate:undefined;if(!value)return;const date=new Date(`${value}T00:00:00.000Z`);return Number.isNaN(date.getTime())?undefined:date}
