export type StoredEvidenceResult={filename:string;path:string;sha256:string};
export function evidenceStoragePath(user:Pick<UserRecord,'organization'>,kind:string,filename:string){const folder=organizationArtifactStorageFolder(kind,user.organization);if(!folder)throw new Error(`No canonical folder is configured for ${kind}.`);return `Organizations/${safeFilePart(user.organization)}/${folder}/${filename}`}
