export async function ensureBrowserOrganizationDocumentFolders(directory:FileSystemDirectoryHandle,organization:string){await directory.getDirectoryHandle(`${safeFilePart(organization,80)} Complete`,{create:true});for(const kind of artifactKinds){const folder=organizationArtifactStorageFolder(kind,organization);if(folder)await directory.getDirectoryHandle(folder,{create:true})}}
export async function organizationFolderNames(root:StorageRoot,recordedOrganizations:string[]=[]){if(isPortableRoot(root)){const response=await portableRequest(root,'organizations');return decodeJsonResponse(response,'Organization listing',decodeOrganizationList)}return Array.from(new Set(recordedOrganizations.filter(validOrganizationFolderName))).sort((a,b)=>a.localeCompare(b))}
